e":"public.search_public_marketplace_v1","owner":"postgres","grants":[{"role":"anon","grantable":false,"privilege":"EXECUTE"},{"role":"authenticated","grantable":false,"privilege":"EXECUTE"},{"role":"postgres","grantable":false,"privilege":"EXECUTE"}],"result":"jsonb","strict":false,"definer":true,"defaults":true,"language":"plpgsql","parallel":"u","arguments":["text","text","text","text","text","text","integer","integer","uuid"],"leakproof":false,"volatility":"s","body_sha256":"850e97f5281a05f310725eda36ca659c9df96a1ac5439ff1eeec7b74768f7aeb","config_sha256":"4897ce422ad20afaf1f959b531ef5e9273ddf5a7bf27489f71e942122b40ea20","definition_sha256":"e32ba10a682ce51e984923badaa388ee43d7b32e81124c0598cc7336b011c121"}]}'::jsonb THEN 'after' ELSE 'unknown' END state
 FROM base CROSS JOIN target
)
SELECT jsonb_build_object('format','selqiro-account-listing-read-fence-20261123-v1',
 'stage','preflight','state',state,'recognized',state IN ('before','after'),'read_only',true,
 'account_rows_read',false,'account_rows_exported',false,
 'base_fingerprint',encode(sha256(convert_to(b::text,'UTF8')),'hex'),
 'target_fingerprint',encode(sha256(convert_to(t::text,'UTF8')),'hex'),
 'fence_verified',state='after') INTO observed FROM evaluated;
 IF observed->>'state' IS DISTINCT FROM 'before' THEN
  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCOUNT_LISTING_READ_SCHEMA_MISMATCH';
 END IF;
END;
$profile_guard$;
-- Account eligibility before count/page or public detail assembly.
CREATE OR REPLACE FUNCTION public.search_public_listings_v1(
  p_search_query text default '',
  p_category text default null,
  p_subcategory text default null,
  p_detail_category text default null,
  p_condition text default null,
  p_location_query text default '',
  p_result_limit integer default 24,
  p_result_offset integer default 0
)
returns jsonb
language plpgsql stable security definer
set search_path = pg_catalog, public, auth, pg_temp
-- Optional predicates must be planned using this call's actual search inputs.
-- This setting is local to the function; it does not alter the caller/session default.
set plan_cache_mode = force_custom_plan
as $function$
declare
  v_query text := btrim(coalesce(p_search_query, ''));
  v_location text := btrim(coalesce(p_location_query, ''));
  v_category text := nullif(btrim(p_category), '');
  v_subcategory text := nullif(btrim(p_subcategory), '');
  v_detail text := nullif(btrim(p_detail_category), '');
  v_condition text := nullif(btrim(p_condition), '');
  v_actor uuid := auth.uid();
  v_tsquery tsquery;
  v_result jsonb;
begin
  if char_length(v_query) > 160 or char_length(v_location) > 160 then
    raise exception 'listing_search_text_too_long' using errcode = '22023';
  end if;
  if p_result_limit is null or p_result_limit < 1 or p_result_limit > 60
    or p_result_offset is null or p_result_offset < 0 or p_result_offset > 100000 then
    raise exception 'listing_search_pagination_invalid' using errcode = '22023';
  end if;
  if (v_category is not null and (char_length(v_category) > 120 or v_category !~ '^[a-z][a-z0-9_]*$'))
    or (v_subcategory is not null and (char_length(v_subcategory) > 160 or v_subcategory !~ '^[a-z][a-z0-9_]*$'))
    or (v_detail is not null and (char_length(v_detail) > 160 or v_detail !~ '^[a-z][a-z0-9_]*$'))
    or (v_subcategory is not null and v_category is null)
    or (v_detail is not null and v_subcategory is null) then
    raise exception 'listing_search_category_path_invalid' using errcode = '22023';
  end if;
  if v_condition is not null and v_condition not in ('new', 'used', 'damaged') then
    raise exception 'listing_search_condition_invalid' using errcode = '22023';
  end if;
  -- Plain words are ANDed. No user-controlled SQL, FTS syntax or implicit AI query.
  -- The old search_vector contains raw location and arbitrary details: do not use it.
  v_tsquery := plainto_tsquery('pg_catalog.simple'::regconfig, v_query);
  with viewer_hidden AS MATERIALIZED (SELECT provider_identity_id FROM provider_controls_private.hidden_providers
 WHERE viewer_user_id=v_actor AND hidden_until>statement_timestamp()), matched as materialized (
    select l.id, l.created_at, l.title, left(l.description, 280) as description_preview,
      l.price, l.price_amount, l.category, l.subcategory, l.condition, l.country, l.city,
      case when jsonb_typeof(l.details -> 'detailCategory') = 'string'
        then l.details ->> 'detailCategory' else null end as detail_category,
      l.image as fallback_image, ip.display_name as seller_name, ip.slug as seller_slug,
      ip.avatar_url as seller_avatar_url, i.type as seller_type
    from public.listings l
    join lateral (
      select account_identity.* from public.identities account_identity
      left join public.business_accounts account_business on account_business.id = account_identity.business_account_id
      where account_identity.id = l.identity_id and account_identity.status = 'active'
        and account_identity.type in ('private','business')
        and account_lifecycle_private.account_is_available(
          case when account_identity.type = 'private' then account_identity.user_id else account_business.owner_user_id end)
      offset 0
    ) i on true
    join public.identity_profiles ip on ip.identity_id = i.id
    where NOT EXISTS(SELECT 1 FROM viewer_hidden vh WHERE vh.provider_identity_id=l.identity_id) and l.status = 'active'
      and (l.active_until is null or l.active_until > now())
      and (v_query = '' or
        public.public_listing_search_document_v1(l.title, l.description, l.category, l.subcategory, l.details) @@ v_tsquery)
      and (v_category is null or l.category = v_category)
      and (v_subcategory is null or l.subcategory = v_subcategory)
      and (v_detail is null or (jsonb_typeof(l.details -> 'detailCategory') = 'string'
        and l.details ->> 'detailCategory' = v_detail))
      and (v_condition is null or l.condition = v_condition)
      and (v_location = '' or strpos(lower(coalesce(l.city, '') || ' ' || coalesce(l.country, '')), lower(v_location)) > 0)
      -- Preserve the existing account-block meaning, now before count/pagination.
      -- This is not a new business/identity-level block policy.
      and not exists (
        select 1 from public.user_blocks b
        where v_actor is not null and (
          (b.blocker_id = v_actor and b.blocked_id = l.user_id)
          or (b.blocked_id = v_actor and b.blocker_id = l.user_id)
        )
      )
  ), page as (
    select m.* from matched m
    order by m.created_at desc, m.id desc
    limit p_result_limit offset p_result_offset
  ), cards as (
    select p.id, p.created_at, jsonb_build_object(
      'content_type', 'listing', 'content_id', p.id::text,
      'title', p.title, 'description_preview', p.description_preview,
      'price', p.price,
      'price_amount', case when p.price_amount >= 0 and p.price_amount::text not in ('NaN','Infinity','-Infinity')
        then p.price_amount::text else null end,
      -- Legacy listings have no canonical currency column. Never invent EUR.
      'currency', null,
      'category', p.category, 'subcategory', p.subcategory,
      'detail_category', p.detail_category, 'condition', p.condition,
      'country', p.country, 'city', p.city,
      'image_url', coalesce(img.thumb_url, img.medium_url, img.original_url, p.fallback_image),
      'seller_name', p.seller_name, 'seller_slug', p.seller_slug,
      'seller_avatar_url', p.seller_avatar_url, 'seller_type', p.seller_type,
      'created_at', p.created_at
    ) as card
    from page p
    left join lateral (
      select li.thumb_url, li.medium_url, li.original_url from public.listing_images li
      where li.listing_id = p.id
      order by li.is_primary desc nulls last, li.sort_order asc nulls last,
        li.created_at asc nulls last, li.id asc
      limit 1
    ) img on true
  ), totals as (select count(*) as n from matched)
  select jsonb_build_object(
    'schema_version', 1, 'content_scope', 'ordinary_listings', 'sort', 'newest',
    'items', coalesce((select jsonb_agg(c.card order by c.created_at desc, c.id desc) from cards c), '[]'::jsonb),
    'total_count', t.n::text, 'result_limit', p_result_limit, 'result_offset', p_result_offset,
    'has_more', t.n > p_result_offset::bigint + p_result_limit,
    'next_offset', case when t.n > p_result_offset::bigint + p_result_limit
      and p_result_offset + p_result_limit <= 100000 then p_result_offset + p_result_limit else null end,
    'window_limit_reached', t.n > p_result_offset::bigint + p_result_limit
      and p_result_offset + p_result_limit > 100000
  ) into v_result from totals t;
  return v_result;
end;
$function$;

-- Account eligibility before count/page or public detail assembly.
CREATE OR REPLACE FUNCTION public.search_public_listings_v2(p_search_query text DEFAULT ''::text, p_category text DEFAULT NULL::text, p_subcategory text DEFAULT NULL::text, p_detail_category text DEFAULT NULL::text, p_condition text DEFAULT NULL::text, p_location_query text DEFAULT ''::text, p_result_limit integer DEFAULT 24, p_result_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  v_query text := btrim(coalesce(p_search_query, ''));
  v_location text := btrim(coalesce(p_location_query, ''));
  v_category text := nullif(btrim(p_category), '');
  v_subcategory text := nullif(btrim(p_subcategory), '');
  v_detail text := nullif(btrim(p_detail_category), '');
  v_condition text := nullif(btrim(p_condition), '');
  v_actor uuid := public.listing_actor_uid_hosted_v1();
  v_tsquery tsquery;
  v_result jsonb;
begin
  if char_length(v_query) > 160 or char_length(v_location) > 160 then
    raise exception 'listing_search_text_too_long' using errcode = '22023';
  end if;
  if p_result_limit is null or p_result_limit < 1 or p_result_limit > 60
    or p_result_offset is null or p_result_offset < 0 or p_result_offset > 100000 then
    raise exception 'listing_search_pagination_invalid' using errcode = '22023';
  end if;
  if (v_category is not null and (char_length(v_category) > 120 or v_category !~ '^[a-z][a-z0-9_]*$'))
    or (v_subcategory is not null and (char_length(v_subcategory) > 160 or v_subcategory !~ '^[a-z][a-z0-9_]*$'))
    or (v_detail is not null and (char_length(v_detail) > 160 or v_detail !~ '^[a-z][a-z0-9_]*$'))
    or (v_subcategory is not null and v_category is null)
    or (v_detail is not null and v_subcategory is null) then
    raise exception 'listing_search_category_path_invalid' using errcode = '22023';
  end if;
  if v_condition is not null and v_condition not in ('new', 'used', 'damaged') then
    raise exception 'listing_search_condition_invalid' using errcode = '22023';
  end if;
  -- Plain words are ANDed. No user-controlled SQL, FTS syntax or implicit AI query.
  -- The old search_vector contains raw location and arbitrary details: do not use it.
  v_tsquery := plainto_tsquery('pg_catalog.simple'::regconfig, v_query);
  with viewer_hidden AS MATERIALIZED (SELECT provider_identity_id FROM provider_controls_private.hidden_providers
 WHERE viewer_user_id=v_actor AND hidden_until>statement_timestamp()), matched as materialized (
    select l.id, l.created_at, l.title, left(l.description, 280) as description_preview,
      l.price, l.price_amount, l.price_kind, l.currency, l.price_revision, l.category, l.subcategory, l.condition, l.country, l.city,
      case when jsonb_typeof(l.details -> 'detailCategory') = 'string'
        then l.details ->> 'detailCategory' else null end as detail_category,
      l.image as fallback_image, ip.display_name as seller_name, ip.slug as seller_slug,
      ip.avatar_url as seller_avatar_url, i.type as seller_type
    from public.listings l
    join lateral (
      select account_identity.* from public.identities account_identity
      left join public.business_accounts account_business on account_business.id = account_identity.business_account_id
      where account_identity.id = l.identity_id and account_identity.status = 'active'
        and account_identity.type in ('private','business')
        and account_lifecycle_private.account_is_available(
          case when account_identity.type = 'private' then account_identity.user_id else account_business.owner_user_id end)
      offset 0
    ) i on true
    join public.identity_profiles ip on ip.identity_id = i.id
    where NOT EXISTS(SELECT 1 FROM viewer_hidden vh WHERE vh.provider_identity_id=l.identity_id) and l.status = 'active'
      and (l.active_until is null or l.active_until > now())
      and (v_query = '' or
        public.public_listing_search_document_v1(l.title, l.description, l.category, l.subcategory, l.details) @@ v_tsquery)
      and (v_category is null or l.category = v_category)
      and (v_subcategory is null or l.subcategory = v_subcategory)
      and (v_detail is null or (jsonb_typeof(l.details -> 'detailCategory') = 'string'
        and l.details ->> 'detailCategory' = v_detail))
      and (v_condition is null or l.condition = v_condition)
      and (v_location = '' or strpos(lower(coalesce(l.city, '') || ' ' || coalesce(l.country, '')), lower(v_location)) > 0)
      -- Preserve the existing account-block meaning, now before count/pagination.
      -- This is not a new business/identity-level block policy.
      and not exists (
        select 1 from public.user_blocks b
        where v_actor is not null and (
          (b.blocker_id = v_actor and b.blocked_id = l.user_id)
          or (b.blocked_id = v_actor and b.blocker_id = l.user_id)
        )
      )
  ), page as (
    select m.* from matched m
    order by m.created_at desc, m.id desc
    limit p_result_limit offset p_result_offset
  ), cards as (
    select p.id, p.created_at, jsonb_build_object(
      'content_type', 'listing', 'content_id', p.id::text,
      'title', p.title, 'description_preview', p.description_preview,
      'price', public.listing_price_read_model_v1(p.price_kind,p.price_amount,
        p.currency,p.price_revision,p.price),
      'category', p.category, 'subcategory', p.subcategory,
      'detail_category', p.detail_category, 'condition', p.condition,
      'country', p.country, 'city', p.city,
      'image_url', coalesce(img.thumb_url, img.medium_url, img.original_url, p.fallback_image),
      'seller_name', p.seller_name, 'seller_slug', p.seller_slug,
      'seller_avatar_url', p.seller_avatar_url, 'seller_type', p.seller_type,
      'created_at', p.created_at
    ) as card
    from page p
    left join lateral (
      select li.thumb_url, li.medium_url, li.original_url from public.listing_images li
      where li.listing_id = p.id
      order by li.is_primary desc nulls last, li.sort_order asc nulls last,
        li.created_at asc nulls last, li.id asc
      limit 1
    ) img on true
  ), totals as (select count(*) as n from matched)
  select jsonb_build_object(
    'schema_version', 2, 'content_scope', 'ordinary_listings', 'sort', 'newest',
    'items', coalesce((select jsonb_agg(c.card order by c.created_at desc, c.id desc) from cards c), '[]'::jsonb),
    'total_count', t.n::text, 'result_limit', p_result_limit, 'result_offset', p_result_offset,
    'has_more', t.n > p_result_offset::bigint + p_result_limit,
    'next_offset', case when t.n > p_result_offset::bigint + p_result_limit
      and p_result_offset + p_result_limit <= 100000 then p_result_offset + p_result_limit else null end,
    'window_limit_reached', t.n > p_result_offset::bigint + p_result_limit
      and p_result_offset + p_result_limit > 100000
  ) into v_result from totals t;
  return v_result;
end;
$function$;

-- Account eligibility before count/page or public detail assembly.
CREATE OR REPLACE FUNCTION public.search_public_marketplace_v1(p_search_query text DEFAULT '',p_category text DEFAULT NULL,
 p_subcategory text DEFAULT NULL,p_detail_category text DEFAULT NULL,p_condition text DEFAULT NULL,
 p_location_query text DEFAULT '',p_result_limit integer DEFAULT 24,p_result_offset integer DEFAULT 0,
 p_identity_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path=pg_catalog,public,auth,pg_temp SET plan_cache_mode='force_custom_plan' AS $f$
DECLARE q text:=btrim(coalesce(p_search_query,''));loc text:=btrim(coalesce(p_location_query,''));
 cat text:=nullif(btrim(p_category),'');sub text:=nullif(btrim(p_subcategory),'');
 detail text:=nullif(btrim(p_detail_category),'');cond text:=nullif(btrim(p_condition),'');
 actor uuid:=public.listing_actor_uid_hosted_v1();query tsquery;result jsonb;
BEGIN
 IF char_length(q)>160 OR char_length(loc)>160 OR p_result_limit IS NULL OR p_result_limit NOT BETWEEN 1 AND 60
  OR p_result_offset IS NULL OR p_result_offset NOT BETWEEN 0 AND 100000 THEN
  RAISE EXCEPTION 'marketplace_search_input' USING ERRCODE='22023'; END IF;
 IF (cat IS NOT NULL AND (length(cat)>120 OR cat!~'^[a-z][a-z0-9_]*$'))
  OR (sub IS NOT NULL AND (length(sub)>160 OR sub!~'^[a-z][a-z0-9_]*$' OR cat IS NULL))
  OR (detail IS NOT NULL AND (length(detail)>160 OR detail!~'^[a-z][a-z0-9_]*$' OR sub IS NULL))
  OR (cond IS NOT NULL AND cond NOT IN('new','used','damaged'))
  OR (cat='horses' AND (detail IS NOT NULL OR (sub IS NOT NULL AND sub NOT IN('sale','free_transfer','lease','co_rider','wanted')))) THEN
  RAISE EXCEPTION 'marketplace_search_filters' USING ERRCODE='22023'; END IF;
 query:=plainto_tsquery('pg_catalog.simple'::regconfig,q);
 WITH viewer_hidden AS MATERIALIZED (SELECT provider_identity_id FROM provider_controls_private.hidden_providers
 WHERE viewer_user_id=actor AND hidden_until>statement_timestamp()), ordinary AS MATERIALIZED(
  SELECT 'listing'::text content_type,l.id::text content_id,l.id numeric_id,NULL::uuid horse_id,l.created_at,
   jsonb_build_object('content_type','listing','content_id',l.id::text,'offer_type',NULL,
    'title',l.title,'description_preview',left(l.description,280),
    'price',public.listing_price_read_model_v1(l.price_kind,l.price_amount,l.currency,l.price_revision,l.price),
    'category',l.category,'subcategory',l.subcategory,
    'detail_category',CASE WHEN jsonb_typeof(l.details->'detailCategory')='string' THEN l.details->>'detailCategory' END,
    'condition',l.condition,'country',l.country,'city',l.city,
    'image_url',coalesce(img.thumb_url,img.medium_url,img.original_url,l.image),
    'seller_name',ip.display_name,'seller_slug',ip.slug,'seller_avatar_url',ip.avatar_url,'seller_type',i.type,'created_at',l.created_at) card
  FROM public.listings l JOIN LATERAL (
   SELECT account_identity.* FROM public.identities account_identity
   LEFT JOIN public.business_accounts account_business ON account_business.id=account_identity.business_account_id
   WHERE account_identity.id=l.identity_id AND account_identity.status='active'
    AND account_identity.type IN ('private','business')
    AND account_lifecycle_private.account_is_available(
     CASE WHEN account_identity.type='private' THEN account_identity.user_id ELSE account_business.owner_user_id END)
   OFFSET 0
  ) i ON true
  JOIN public.identity_profiles ip ON ip.identity_id=i.id
  LEFT JOIN LATERAL(SELECT li.thumb_url,li.medium_url,li.original_url FROM public.listing_images li WHERE li.listing_id=l.id
   ORDER BY li.is_primary DESC NULLS LAST,li.sort_order ASC NULLS LAST,li.created_at ASC NULLS LAST,li.id LIMIT 1) img ON true
  WHERE NOT EXISTS(SELECT 1 FROM viewer_hidden vh WHERE vh.provider_identity_id=l.identity_id) AND l.status='active' AND (l.active_until IS NULL OR l.active_until>now())
   AND (p_identity_id IS NULL OR l.identity_id=p_identity_id)
   AND (q='' OR public.public_listing_search_document_v1(l.title,l.description,l.category,l.subcategory,l.details)@@query)
   AND (cat IS NULL OR l.category=cat) AND (sub IS NULL OR l.subcategory=sub)
   AND (detail IS NULL OR (jsonb_typeof(l.details->'detailCategory')='string' AND l.details->>'detailCategory'=detail))
   AND (cond IS NULL OR l.condition=cond)
   AND (loc='' OR strpos(lower(coalesce(l.city,'')||' '||coalesce(l.country,'')),lower(loc))>0)
   AND NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE actor IS NOT NULL AND
    ((b.blocker_id=actor AND b.blocked_id=l.user_id) OR (b.blocked_id=actor AND b.blocker_id=l.user_id)))
 ), horses AS MATERIALIZED(
  SELECT 'horse_offer'::text content_type,h.id::text content_id,NULL::bigint numeric_id,h.id horse_id,h.created_at,
   jsonb_build_object('content_type','horse_offer','content_id',h.id,'offer_type',h.offer_type,
    'title',h.title,'description_preview',left(h.description,280),'price',horse_publication_private.public_price(h),
    'category','horses','subcategory',h.offer_type,'detail_category',NULL,'condition',NULL,'country','EE',
    'city',CASE WHEN h.offer_type='wanted' THEN h.details#>>'{wanted,search_area,city_or_municipality}' ELSE h.city END,
    'image_url',img.original_url,'seller_name',ip.display_name,'seller_slug',ip.slug,
    'seller_avatar_url',ip.avatar_url,'seller_type',i.type,'created_at',h.created_at) card
  FROM public.horse_offers h JOIN public.identities i ON i.id=h.identity_id AND i.status='active'
  JOIN public.identity_profiles ip ON ip.identity_id=i.id
  LEFT JOIN LATERAL(SELECT im.original_url FROM public.horse_offer_images im WHERE im.horse_offer_id=h.id
   ORDER BY im.is_primary DESC,im.sort_order,im.created_at,im.id LIMIT 1) img ON true
  WHERE NOT EXISTS(SELECT 1 FROM viewer_hidden vh WHERE vh.provider_identity_id=h.identity_id) AND horse_publication_private.is_public(h.id) AND (p_identity_id IS NULL OR h.identity_id=p_identity_id)
   AND (cat IS NULL OR cat='horses') AND (sub IS NULL OR h.offer_type=sub) AND detail IS NULL AND cond IS NULL
   AND (q='' OR to_tsvector('pg_catalog.simple'::regconfig,coalesce(h.title,'')||' '||coalesce(h.description,'')||' '||
    coalesce(h.breed,'')||' '||coalesce(h.discipline,'')||' '||coalesce(h.details#>>'{wanted,preferred_breed}',''))@@query)
   AND (loc='' OR strpos(lower(CASE WHEN h.offer_type='wanted' THEN coalesce(h.details#>>'{wanted,search_area,city_or_municipality}','')
     ELSE coalesce(h.city,'') END||' EE'),lower(loc))>0)
   AND NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE actor IS NOT NULL AND
    ((b.blocker_id=actor AND b.blocked_id=h.created_by_user_id) OR (b.blocked_id=actor AND b.blocker_id=h.created_by_user_id)))
 ), matched AS MATERIALIZED(SELECT * FROM ordinary UNION ALL SELECT * FROM horses),
 page AS(SELECT * FROM matched ORDER BY created_at DESC,content_type,numeric_id DESC,horse_id DESC LIMIT p_result_limit OFFSET p_result_offset),
 totals AS(SELECT count(*) n FROM matched)
 SELECT jsonb_build_object('schema_version',1,'content_scope','marketplace','sort','newest',
  'items',coalesce((SELECT jsonb_agg(card ORDER BY created_at DESC,content_type,numeric_id DESC,horse_id DESC) FROM page),'[]'::jsonb),
  'total_count',n::text,'result_limit',p_result_limit,'result_offset',p_result_offset,
  'has_more',n>p_result_offset::bigint+p_result_limit,
  'next_offset',CASE WHEN n>p_result_offset::bigint+p_result_limit AND p_result_offset+p_result_limit<=100000 THEN p_result_offset+p_result_limit END,
  'window_limit_reached',n>p_result_offset::bigint+p_result_limit AND p_result_offset+p_result_limit>100000)
 INTO result FROM totals;
 RETURN result;
END $f$;

-- Account eligibility before count/page or public detail assembly.
CREATE OR REPLACE FUNCTION public.get_public_listing_detail_v1(p_listing_id text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path=pg_catalog,public,auth,pg_temp
SET timezone='UTC'
AS $fn$
DECLARE actor uuid:=public.listing_actor_uid_hosted_v1(); r public.listings%ROWTYPE; seller record; gallery jsonb; image_url text;
  detail_values jsonb; item jsonb:=NULL; has_more boolean:=false; id_value bigint;
BEGIN
  IF p_listing_id IS NULL OR char_length(p_listing_id)>20
     OR p_listing_id !~ '^(0|[1-9][0-9]*|-[1-9][0-9]*)$' THEN
    RAISE EXCEPTION 'public_listing_id_invalid' USING ERRCODE='22023';
  END IF;
  IF p_listing_id::numeric < -9223372036854775808
     OR p_listing_id::numeric > 9223372036854775807 THEN
    RAISE EXCEPTION 'public_listing_id_invalid' USING ERRCODE='22023';
  END IF;
  id_value:=p_listing_id::bigint;
  SELECT l.* INTO r FROM public.listings l
    JOIN public.identities i ON i.id=l.identity_id AND i.status='active'
    JOIN public.identity_profiles ip ON ip.identity_id=i.id
    LEFT JOIN public.business_accounts account_business ON account_business.id=i.business_account_id
    WHERE l.id=id_value AND l.status='active'
      -- Deliberately preserves public detail/search NULL-expiry semantics.
      AND (l.active_until IS NULL OR l.active_until>now())
      AND i.type IN ('private','business')
      AND account_lifecycle_private.account_is_available(
        CASE WHEN i.type='private' THEN i.user_id ELSE account_business.owner_user_id END)
      AND NOT EXISTS (SELECT 1 FROM public.user_blocks b WHERE actor IS NOT NULL
        AND ((b.blocker_id=actor AND b.blocked_id=l.user_id)
          OR (b.blocked_id=actor AND b.blocker_id=l.user_id)));
  IF FOUND THEN
    SELECT ip.display_name,ip.slug,ip.avatar_url,i.type INTO seller
      FROM public.identities i JOIN public.identity_profiles ip ON ip.identity_id=i.id
      WHERE i.id=r.identity_id AND i.status='active';
    -- Small bounded gallery, stable tiebreaks, identical first-image rule to search v2.
    WITH ordered AS (
      SELECT li.id,li.thumb_url,li.medium_url,li.original_url,li.is_primary,li.sort_order,
        row_number() OVER (ORDER BY li.is_primary DESC NULLS LAST,li.sort_order ASC NULLS LAST,
          li.created_at ASC NULLS LAST,li.id ASC) AS position
      FROM public.listing_images li WHERE li.listing_id=r.id
      ORDER BY li.is_primary DESC NULLS LAST,li.sort_order ASC NULLS LAST,
        li.created_at ASC NULLS LAST,li.id ASC LIMIT 11
    ) SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id::text,'thumb_url',o.thumb_url,
        'medium_url',o.medium_url,'original_url',o.original_url,'is_primary',o.is_primary,
        'sort_order',o.sort_order) ORDER BY o.position) FILTER (WHERE o.position<=10),'[]'::jsonb),
        coalesce(bool_or(o.position>10),false)
      INTO gallery,has_more FROM ordered o;
    image_url:=coalesce(gallery->0->>'thumb_url',gallery->0->>'medium_url',
      gallery->0->>'original_url',r.image);
    detail_values:=public.public_listing_detail_values_v1(r);
    item:=jsonb_build_object('content_type','listing','content_id',r.id::text,
      'title',left(r.title,4096),'description',left(r.description,32768),
      'title_truncated',coalesce(char_length(r.title)>4096,false),
      'description_truncated',coalesce(char_length(r.description)>32768,false),
      'price',public.listing_price_read_model_v1(r.price_kind,r.price_amount,r.currency,r.price_revision,r.price),
      'category',r.category,'subcategory',r.subcategory,
      'detail_category',CASE WHEN jsonb_typeof(r.details->'detailCategory')='string'
        THEN r.details->>'detailCategory' ELSE NULL END,
      'condition',r.condition,'country',r.country,'city',r.city,
      'image_url',image_url,'images',gallery,'images_has_more',has_more,
      'details',detail_values->'fields','details_truncated',detail_values->'truncated',
      'seller_name',seller.display_name,'seller_slug',seller.slug,'seller_avatar_url',seller.avatar_url,
      'seller_type',seller.type,'created_at',r.created_at,'active_until',r.active_until);
  END IF;
  -- Hidden, missing and blocked IDs are indistinguishable. No owner bypass here.
  RETURN jsonb_build_object('schema_version',1,'content_scope','public_ordinary_listing_detail',
    'requested_id',p_listing_id,'item',item);
END $fn$;

DO $profile_guard$
DECLARE observed jsonb;
BEGIN
 -- Catalog only; no account, content, Auth or Storage rows.
WITH prior_profile AS MATERIALIZED (
-- Catalog only; no application/Auth/Storage rows.
WITH foundation_functions AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
  'name',n.nspname||'.'||p.proname,
  'arguments',COALESCE((SELECT jsonb_agg(format_type(a,NULL) ORDER BY ord) FROM unnest(p.proargtypes::oid[]) WITH ORDINALITY x(a,ord)),'[]'::jsonb),
  'result',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'language',l.lanname,
  'definer',p.prosecdef,'volatility',p.provolatile::text,'strict',p.proisstrict,'parallel',p.proparallel::text,'leakproof',p.proleakproof,
  'config_sha256',CASE WHEN p.proconfig IS NULL THEN NULL ELSE encode(sha256(convert_to(p.proconfig::text,'UTF8')),'hex') END,
  'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),
  'body_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'defaults',p.pronargdefaults<>0,
  'grants',COALESCE((SELECT jsonb_agg(jsonb_build_object('role',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type)
   FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a),'[]'::jsonb)) ORDER BY n.nspname,p.proname,p.oid),'[]'::jsonb) value
 FROM (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='account_lifecycle_private' AND p.proname<>'account_is_available') OR (n.nspname='public' AND p.proname='get_my_account_state_v1') ORDER BY n.nspname,p.proname,p.oid LIMIT 4) p
 JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
), foundation AS (
 SELECT jsonb_build_object(
  'schema_owner',(SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname='account_lifecycle_private'),
  'schema_owner_only',NOT EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(COALESCE(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='account_lifecycle_private' AND a.grantee<>n.nspowner),
  'schema_app_denied',NOT EXISTS(SELECT 1 FROM pg_roles r JOIN pg_namespace n ON n.nspname='account_lifecycle_private' WHERE r.rolname IN ('anon','authenticated','service_role') AND (has_schema_privilege(r.oid,n.oid,'USAGE') OR has_schema_privilege(r.oid,n.oid,'CREATE'))),
  'relation_count',(SELECT count(*) FROM (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='account_lifecycle_private' AND c.relkind IN ('r','p','v','m','S','f') LIMIT 3) bounded),
  'table_owner',(SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid=to_regclass('account_lifecycle_private.account_states')),
  'table_kind',(SELECT relkind::text FROM pg_class WHERE oid=to_regclass('account_lifecycle_private.account_states')),
  'rls',(SELECT relrowsecurity FROM pg_class WHERE oid=to_regclass('account_lifecycle_private.account_states')),
  'force_rls',(SELECT relforcerowsecurity FROM pg_class WHERE oid=to_regclass('account_lifecycle_private.account_states')),
  'owner_grants_only',NOT EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=to_regclass('account_lifecycle_private.account_states') AND a.grantee<>c.relowner),
  'column_grants_owner_only',NOT EXISTS(SELECT 1 FROM pg_attribute col JOIN pg_class c ON c.oid=col.attrelid CROSS JOIN LATERAL aclexplode(col.attacl) a WHERE c.oid=to_regclass('account_lifecycle_private.account_states') AND a.grantee<>c.relowner),
  'table_app_denied',NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','service_role') AND
   (has_table_privilege(r.oid,to_regclass('account_lifecycle_private.account_states'),'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege(r.oid,to_regclass('account_lifecycle_private.account_states'),'SELECT,INSERT,UPDATE,REFERENCES'))),
  'columns',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'generated',a.attgenerated::text,'identity',a.attidentity::text,
   'default_sha256',CASE WHEN d.oid IS NULL THEN NULL ELSE encode(sha256(convert_to(pg_get_expr(d.adbin,d.adrelid),'UTF8')),'hex') END) ORDER BY a.attnum)
   FROM (SELECT * FROM pg_attribute WHERE attrelid=to_regclass('account_lifecycle_private.account_states') AND attnum>0 AND NOT attisdropped ORDER BY attnum LIMIT 8) a
   LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum),'[]'::jsonb),
  'constraints',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',con.conname,'kind',con.contype::text,'definition_sha256',encode(sha256(convert_to(pg_get_constraintdef(con.oid),'UTF8')),'hex'),'validated',con.convalidated,'deferrable',con.condeferrable) ORDER BY con.conname)
   FROM (SELECT * FROM pg_constraint WHERE conrelid=to_regclass('account_lifecycle_private.account_states') ORDER BY conname LIMIT 8) con),'[]'::jsonb),
  'table_triggers',(SELECT count(*) FROM (SELECT 1 FROM pg_trigger WHERE tgrelid=to_regclass('account_lifecycle_private.account_states') AND NOT tgisinternal LIMIT 2) bounded),
  'policies',(SELECT count(*) FROM (SELECT 1 FROM pg_policy WHERE polrelid=to_regclass('account_lifecycle_private.account_states') LIMIT 2) bounded),
  'indexes',(SELECT count(*) FROM (SELECT 1 FROM pg_index WHERE indrelid=to_regclass('account_lifecycle_private.account_states') LIMIT 3) bounded),
  'functions',(SELECT value FROM foundation_functions),
  'auth_triggers',COALESCE((SELECT jsonb_agg(jsonb_build_object('definition_sha256',encode(sha256(convert_to(pg_get_triggerdef(t.oid),'UTF8')),'hex'),'name',t.tgname,'function',t.tgfoid::regprocedure::text,'enabled',t.tgenabled::text,'event_mask',t.tgtype,'argument_count',t.tgnargs,
   'arguments_sha256',encode(sha256(t.tgargs),'hex'),'when_sha256',CASE WHEN t.tgqual IS NULL THEN NULL ELSE encode(sha256(convert_to(pg_get_expr(t.tgqual,t.tgrelid),'UTF8')),'hex') END) ORDER BY t.tgname)
   FROM (SELECT * FROM pg_trigger WHERE tgrelid=to_regclass('auth.users') AND NOT tgisinternal ORDER BY tgname LIMIT 4) t),'[]'::jsonb)
 ) value
), scoped_functions AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
  'name',n.nspname||'.'||p.proname,
  'arguments',COALESCE((SELECT jsonb_agg(format_type(a,NULL) ORDER BY ord) FROM unnest(p.proargtypes::oid[]) WITH ORDINALITY x(a,ord)),'[]'::jsonb),
  'result',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'language',l.lanname,
  'definer',p.prosecdef,'volatility',p.provolatile::text,'strict',p.proisstrict,'parallel',p.proparallel::text,'leakproof',p.proleakproof,
  'config_sha256',CASE WHEN p.proconfig IS NULL THEN NULL ELSE encode(sha256(convert_to(p.proconfig::text,'UTF8')),'hex') END,
  'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),
  'body_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'defaults',p.pronargdefaults<>0,
  'grants',COALESCE((SELECT jsonb_agg(jsonb_build_object('role',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type)
   FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a),'[]'::jsonb)) ORDER BY n.nspname,p.proname,p.oid),'[]'::jsonb) value
 FROM (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname IN ('account_lifecycle_private.account_is_available','auth.uid','profile_media_private.public_url','profile_media_private.slot_asset','profile_media_private.slot_url','public.get_public_profile_media_v1','public.get_store_by_slug') ORDER BY n.nspname,p.proname,p.oid LIMIT 12) p
 JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
), ownership_columns AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object('relation',w.relation,'name',w.name,
 'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'generated',a.attgenerated::text,'identity',a.attidentity::text)
 ORDER BY w.relation COLLATE "C",w.name COLLATE "C"),'[]'::jsonb) value
 FROM (VALUES ('auth.users','id'),('auth.users','created_at'),('auth.users','deleted_at'),('auth.users','banned_until'),('public.identities','id'),('public.identities','type'),('public.identities','user_id'),('public.identities','business_account_id'),('public.identities','status'),('public.business_accounts','id'),('public.business_accounts','owner_user_id'),('public.business_accounts','status'),('public.identity_profiles','identity_id'),('public.identity_profiles','slug'),('public.profiles','id'),('public.profiles','store_slug')) w(relation,name)
 JOIN pg_attribute a ON a.attrelid=to_regclass(w.relation) AND a.attname=w.name AND NOT a.attisdropped
), protected_relations AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object('name',name,'kind',c.relkind::text,'owner',pg_get_userbyid(c.relowner),
 'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'observer_select',has_table_privilege(current_user,c.oid,'SELECT')) ORDER BY name COLLATE "C"),'[]'::jsonb) value
 FROM unnest(ARRAY['auth.users','public.business_accounts','public.identities','public.identity_profiles','public.profiles']) name JOIN pg_class c ON c.oid=to_regclass(name)
), protected_indexes AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object('relation',i.indrelid::regclass::text,'name',c.relname,'unique',i.indisunique,
 'primary',i.indisprimary,'valid',i.indisvalid,'ready',i.indisready,
 'definition_sha256',encode(sha256(convert_to(pg_get_indexdef(i.indexrelid),'UTF8')),'hex')) ORDER BY i.indrelid::regclass::text COLLATE "C",c.relname COLLATE "C"),'[]'::jsonb) value
 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid
 WHERE i.indrelid IN (SELECT to_regclass(x) FROM unnest(ARRAY['auth.users','public.business_accounts','public.identities','public.identity_profiles','public.profiles']) x) AND c.relname IN ('users_pkey','business_accounts_pkey','identities_pkey','identity_profiles_identity_id_key','identity_profiles_slug_key','profiles_pkey','profiles_store_slug_key')
), base AS (
 SELECT jsonb_build_object('foundation',(SELECT value FROM foundation),
 'dependencies',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'name' COLLATE "C"),'[]'::jsonb) FROM scoped_functions,jsonb_array_elements(value) x
 WHERE x->>'name' NOT IN ('public.get_store_by_slug','account_lifecycle_private.account_is_available')),
 'relations',(SELECT value FROM protected_relations),'columns',(SELECT value FROM ownership_columns),
 'indexes',(SELECT value FROM protected_indexes),'observer',current_user,
 'roles',(SELECT jsonb_agg(rolname ORDER BY rolname COLLATE "C") FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role'))
 ) value
), target AS (
 SELECT jsonb_build_object('functions',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'name' COLLATE "C"),'[]'::jsonb) FROM scoped_functions,jsonb_array_elements(value) x
 WHERE x->>'name' IN ('public.get_store_by_slug','account_lifecycle_private.account_is_available')),
 'helper_app_denied',NOT EXISTS(SELECT 1 FROM pg_roles r JOIN pg_proc p ON p.oid=to_regprocedure('account_lifecycle_private.account_is_available(uuid)')
 WHERE r.rolname IN ('anon','authenticated','service_role') AND has_function_privilege(r.oid,p.oid,'EXECUTE'))
 ) value
)
SELECT base.value b,target.value t FROM base CROSS JOIN target
), listing_functions AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
  'name',n.nspname||'.'||p.proname,
  'arguments',COALESCE((SELECT jsonb_agg(format_type(a,NULL) ORDER BY ord) FROM unnest(p.proargtypes::oid[]) WITH ORDINALITY x(a,ord)),'[]'::jsonb),
  'result',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'language',l.lanname,
  'definer',p.prosecdef,'volatility',p.provolatile::text,'strict',p.proisstrict,'parallel',p.proparallel::text,'leakproof',p.proleakproof,
  'config_sha256',CASE WHEN p.proconfig IS NULL THEN NULL ELSE encode(sha256(convert_to(p.proconfig::text,'UTF8')),'hex') END,
  'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),
  'body_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'defaults',p.pronargdefaults<>0,
  'grants',COALESCE((SELECT jsonb_agg(jsonb_build_object('role',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type)
   FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a),'[]'::jsonb)) ORDER BY n.nspname,p.proname,p.oid),'[]'::jsonb) value
 FROM (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname IN ('public.search_public_listings_v1','public.search_public_listings_v2','public.search_public_marketplace_v1','public.get_public_listing_detail_v1','public.listing_actor_uid_hosted_v1','public.public_listing_search_document_v1') ORDER BY n.nspname,p.proname,p.oid LIMIT 8) p
 JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
)
, listing_relations AS (
 SELECT jsonb_agg(jsonb_build_object('name',name,'kind',c.relkind::text,'owner',pg_get_userbyid(c.relowner),
  'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'observer_select',has_table_privilege(current_user,c.oid,'SELECT')) ORDER BY name COLLATE "C") value
 FROM unnest(ARRAY['public.listings','public.listing_images','public.user_blocks','provider_controls_private.hidden_providers']) name JOIN pg_class c ON c.oid=to_regclass(name)
), listing_columns AS (
 SELECT jsonb_agg(jsonb_build_object('relation',w.relation,'name',w.name,'type',format_type(a.atttypid,a.atttypmod),
  'not_null',a.attnotnull,'generated',a.attgenerated::text,'identity',a.attidentity::text) ORDER BY w.relation COLLATE "C",w.name COLLATE "C") value
 FROM (VALUES ('public.listings','id'),('public.listings','identity_id'),('public.listings','user_id'),('public.listings','status'),('public.listings','active_until'),('public.listing_images','id'),('public.listing_images','listing_id'),('public.user_blocks','blocker_id'),('public.user_blocks','blocked_id'),('provider_controls_private.hidden_providers','viewer_user_id'),('provider_controls_private.hidden_providers','provider_identity_id'),('provider_controls_private.hidden_providers','hidden_until')) w(relation,name) JOIN pg_attribute a ON a.attrelid=to_regclass(w.relation) AND a.attname=w.name AND NOT a.attisdropped
), listing_indexes AS (
 SELECT jsonb_agg(jsonb_build_object('relation',i.indrelid::regclass::text,'name',c.relname,'unique',i.indisunique,
  'primary',i.indisprimary,'valid',i.indisvalid,'ready',i.indisready,
  'definition_sha256',encode(sha256(convert_to(pg_get_indexdef(i.indexrelid),'UTF8')),'hex')) ORDER BY i.indrelid::regclass::text COLLATE "C",c.relname COLLATE "C") value
 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid
 WHERE i.indrelid IN (SELECT to_regclass(x) FROM unnest(ARRAY['public.listings','public.listing_images','public.user_blocks','provider_controls_private.hidden_providers']) x) AND c.relname IN ('listings_pkey','listings_public_keywords_v1_gin','listings_identity_id_idx','idx_listings_category','idx_listing_images_listing_id','user_blocks_blocker_id_blocked_id_key','user_blocks_blocked_blocker_idx_v1','hidden_providers_pkey','hidden_providers_active_idx')
), base AS (
 SELECT jsonb_build_object('accepted_profile_base',prior_profile.b,'accepted_profile_target',prior_profile.t,
  'dependencies',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'name' COLLATE "C"),'[]'::jsonb) FROM listing_functions,jsonb_array_elements(value) x WHERE x->>'name' IN ('public.listing_actor_uid_hosted_v1','public.public_listing_search_document_v1')),
  'relations',(SELECT value FROM listing_relations),'columns',(SELECT value FROM listing_columns),
  'indexes',(SELECT value FROM listing_indexes)) value FROM prior_profile
), target AS (
 SELECT jsonb_build_object('functions',(SELECT coalesce(jsonb_agg(x ORDER BY x->>'name' COLLATE "C"),'[]'::jsonb) FROM listing_functions,jsonb_array_elements(value) x WHERE x->>'name' IN ('public.search_public_listings_v1','public.search_public_listings_v2','public.search_public_marketplace_v1','public.get_public_listing_detail_v1'))) value
)
, evaluated AS (
